import { expect, test } from "@playwright/test";
import { Pool } from "pg";

const pool = new Pool({
  connectionString:
    process.env.E2E_DATABASE_URL ??
    "postgresql://localhost:5432/easy_check_in_e2e",
});

test.afterAll(async () => {
  await pool.end();
});

/**
 * The organization plugin's own schema is regenerated by `npm run auth:generate`,
 * which would silently drop anything added to it by hand. This index is the only
 * thing stopping a person holding two memberships of one organization, so it is
 * asserted here rather than trusted.
 */
test("member_one_per_user_per_org survives in the database", async () => {
  const { rows } = await pool.query<{ indexdef: string }>(
    `SELECT indexdef FROM pg_indexes
      WHERE tablename = 'member' AND indexname = 'member_one_per_user_per_org'`,
  );

  expect(
    rows.length,
    "the unique membership index is missing, most likely because the auth schema was regenerated",
  ).toBe(1);
  expect(rows[0].indexdef).toContain("UNIQUE");
});

test("the database refuses a second membership of the same organization", async () => {
  const client = await pool.connect();

  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO organization (id, name, slug, created_at)
       VALUES ('constraint_org', 'Constraint Org', 'constraint-org', now())`,
    );
    await client.query(
      `INSERT INTO "user" (id, name, email, email_verified, created_at, updated_at)
       VALUES ('constraint_user', 'Constraint User', 'constraint@example.invalid',
               false, now(), now())`,
    );
    await client.query(
      `INSERT INTO member (id, organization_id, user_id, role, created_at)
       VALUES ('constraint_a', 'constraint_org', 'constraint_user', 'member', now())`,
    );

    await expect(
      client.query(
        `INSERT INTO member (id, organization_id, user_id, role, created_at)
         VALUES ('constraint_b', 'constraint_org', 'constraint_user', 'owner', now())`,
      ),
    ).rejects.toThrow(/duplicate key|unique/i);
  } finally {
    // Rolled back either way, so the suite leaves nothing behind.
    await client.query("ROLLBACK");
    client.release();
  }
});
